import{_ as t,o,c as a,a2 as n}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Introduction to Lodestone","description":"","frontmatter":{},"headers":[],"relativePath":"00-introduction-to-lodestone.md","filePath":"00-introduction-to-lodestone.md"}'),r={name:"00-introduction-to-lodestone.md"};function s(i,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction-to-lodestone" tabindex="-1">Introduction to Lodestone <a class="header-anchor" href="#introduction-to-lodestone" aria-label="Permalink to &quot;Introduction to Lodestone&quot;">​</a></h1><p><em>What it is, how it thinks, and how the pieces fit together</em></p><hr><h2 id="what-is-lodestone" tabindex="-1">What Is Lodestone? <a class="header-anchor" href="#what-is-lodestone" aria-label="Permalink to &quot;What Is Lodestone?&quot;">​</a></h2><p>Lodestone is a product management platform designed to help product managers turn messy, fragmented feedback into clear, coherent plans — and share those plans through strong narratives and presentations.</p><p>At its core, Lodestone helps PMs:</p><ul><li>Capture product ideas from real conversations</li><li>Shape those ideas into structured plans</li><li>Communicate WHAT is being built, WHY it matters, and WHEN it is coming</li><li>Achieve organizational alignment through storytelling</li></ul><p>Lodestone is built first and foremost for the <strong>individual Product Manager</strong>, while steadily evolving to support <strong>Product Leaders managing teams of PMs</strong>.</p><hr><h2 id="what-lodestone-is-not" tabindex="-1">What Lodestone Is Not <a class="header-anchor" href="#what-lodestone-is-not" aria-label="Permalink to &quot;What Lodestone Is Not&quot;">​</a></h2><p>Lodestone is intentionally focused. It is not:</p><ul><li><strong>A developer ticketing system</strong> — it doesn&#39;t replace JIRA, Asana, or Azure DevOps</li><li><strong>A project management system</strong> — it doesn&#39;t replace MS Project, Monday.com, or task-based execution tools</li><li><strong>A workflow enforcer</strong> — it doesn&#39;t mandate rigid processes or linear paths</li></ul><p>Lodestone sits between customer reality and delivery execution. It focuses exclusively on the product management layer — capturing intent, building plans, and communicating them clearly.</p><hr><h2 id="the-core-belief" tabindex="-1">The Core Belief <a class="header-anchor" href="#the-core-belief" aria-label="Permalink to &quot;The Core Belief&quot;">​</a></h2><p>Lodestone is built on a simple but strong belief:</p><blockquote><p>Product managers do their best work when they spend more time sharing and refining plans with stakeholders, not assembling artifacts.</p></blockquote><p>A user knows Lodestone is working for them when:</p><ul><li>They are creating and sharing plans more frequently</li><li>They are presenting roadmaps and strategies more often</li><li>They are spending less time formatting and more time aligning people</li></ul><hr><h2 id="the-planning-stack" tabindex="-1">The Planning Stack <a class="header-anchor" href="#the-planning-stack" aria-label="Permalink to &quot;The Planning Stack&quot;">​</a></h2><p>Lodestone is organized around core objects that reflect how product work actually unfolds in the real world:</p><table tabindex="0"><thead><tr><th>Object</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Extracts</strong></td><td>Raw ideas surfaced from meeting transcripts and competitive reports using AI</td></tr><tr><td><strong>Backlog</strong></td><td>Concrete initiatives a product team may pursue, organized by type (Features, Epics, Bugs, etc.)</td></tr><tr><td><strong>Documents</strong></td><td>Written artifacts that explain and justify Features</td></tr><tr><td><strong>Roadmaps</strong></td><td>Narrative plans that explain WHAT is being built and WHY</td></tr><tr><td><strong>Releases</strong></td><td>Progress views that communicate WHEN things are happening</td></tr><tr><td><strong>Strategy</strong></td><td>Long-term investment decisions that force tradeoffs over time</td></tr><tr><td><strong>Competitive Intelligence</strong></td><td>AI-generated competitor tracking and market analysis</td></tr><tr><td><strong>Financial Forecast</strong></td><td>Financial modeling (NPV, ROI, IRR) for individual Features</td></tr><tr><td><strong>Bento Grids</strong></td><td>Visual release summaries designed for sharing with stakeholders and customer-facing teams</td></tr></tbody></table><p>This stack is <strong>not prescriptive</strong>. Users may start at any point depending on their needs. A PM might begin by uploading a customer call transcript, or they might start by sketching out a roadmap. Lodestone accommodates both.</p><hr><h2 id="what-why-and-when" tabindex="-1">WHAT, WHY, and WHEN <a class="header-anchor" href="#what-why-and-when" aria-label="Permalink to &quot;WHAT, WHY, and WHEN&quot;">​</a></h2><p>One of Lodestone&#39;s most important mental models is the separation of planning concerns. Different modules answer different questions:</p><ul><li><strong>Roadmaps</strong> answer: WHAT are we building, and WHY does it matter?</li><li><strong>Releases</strong> answer: WHEN is it happening, and how is progress tracking?</li><li><strong>Strategy</strong> answers: Where are we intentionally investing over time, and what tradeoffs are we making?</li></ul><p>Keeping these questions separate prevents overloaded artifacts and keeps communication clear. A roadmap that tries to also track delivery status becomes harder to share. A release board that tries to explain strategic rationale becomes harder to read.</p><hr><h2 id="objects-over-workflows" tabindex="-1">Objects Over Workflows <a class="header-anchor" href="#objects-over-workflows" aria-label="Permalink to &quot;Objects Over Workflows&quot;">​</a></h2><p>Lodestone is intentionally <strong>object-centric</strong>, not workflow-centric.</p><p>Product teams don&#39;t follow linear paths. Planning is iterative. Different people enter the system at different stages. Rather than enforcing a single &quot;right&quot; flow, Lodestone lets:</p><ul><li>Features exist independently of any roadmap or release</li><li>Objects relate to each other flexibly</li><li>Structure emerge through usage, not prescription</li></ul><p>This means you&#39;re never forced to complete one step before starting another. The platform adapts to how you actually work.</p><hr><h2 id="ai-as-an-assistant-not-an-author" tabindex="-1">AI as an Assistant, Not an Author <a class="header-anchor" href="#ai-as-an-assistant-not-an-author" aria-label="Permalink to &quot;AI as an Assistant, Not an Author&quot;">​</a></h2><p>AI is woven throughout Lodestone — in Extracts, Documents, Roadmaps, Strategy exports, and more. It exists to:</p><ul><li>Eliminate blank-page work</li><li>Speed up iteration</li><li>Surface insights from raw data</li></ul><p>AI does <strong>not</strong> replace human judgment. All AI-generated content in Lodestone is editable, clearly marked, and designed as a starting point — not a finished product. You stay in control of everything the platform produces.</p><hr><h2 id="key-design-principles" tabindex="-1">Key Design Principles <a class="header-anchor" href="#key-design-principles" aria-label="Permalink to &quot;Key Design Principles&quot;">​</a></h2><p>A few principles shape how Lodestone behaves across every module:</p><p><strong>Guidance over enforcement</strong> — Lodestone provides strong defaults and opinionated visualizations, but rarely forces a single way of doing things. You can adapt it to your context.</p><p><strong>Narration over execution</strong> — Execution lives in delivery tools. Lodestone exists to explain and align. Its outputs are presentations, exports, and shared artifacts — not tickets or task lists.</p><p><strong>Scarcity as a forcing function</strong> — Where Lodestone does enforce constraints (like exactly three Strategy dimensions), it does so intentionally. Constraints force meaningful choices. When everything is a priority, nothing is.</p><hr><h2 id="the-dashboard" tabindex="-1">The Dashboard <a class="header-anchor" href="#the-dashboard" aria-label="Permalink to &quot;The Dashboard&quot;">​</a></h2><p>When you log in to Lodestone, the Dashboard is the first thing you see. Called the <strong>Command Deck</strong>, it organizes recent workspace activity into five columns — Collecting Data, Processing Data, Making Plans, Aligning Plans, and Executing Plans — reflecting the full product lifecycle at a glance.</p><p>New items (objects created or updated since your last visit) are highlighted automatically. The columns can be reordered by drag-and-drop to match your workflow.</p><p>See the Dashboard module documentation for full details.</p><hr><h2 id="copilot" tabindex="-1">Copilot <a class="header-anchor" href="#copilot" aria-label="Permalink to &quot;Copilot&quot;">​</a></h2><p>Copilot is Lodestone&#39;s built-in AI assistant, accessible from the <strong>Copilot</strong> button in the left-hand navigation on every page. It answers questions about the platform and product management best practices, and can take actions in your workspace — creating features, building roadmaps, generating documents — when you ask it to.</p><p>See the Copilot module documentation for full details.</p><hr><h2 id="how-the-module-docs-are-organized" tabindex="-1">How the Module Docs Are Organized <a class="header-anchor" href="#how-the-module-docs-are-organized" aria-label="Permalink to &quot;How the Module Docs Are Organized&quot;">​</a></h2><p>Each Lodestone module has four documentation pages:</p><ul><li><strong>Overview &amp; Concepts</strong> — what the module is, why you&#39;d use it, key terminology</li><li><strong>How-tos &amp; Workflows</strong> — step-by-step guides for the main user journeys</li><li><strong>Advanced Features &amp; Customization</strong> — deeper configuration, integrations, and power-user options</li><li><strong>Troubleshooting &amp; FAQs</strong> — common problems, edge cases, and answers to frequent questions</li></ul><p>If you&#39;re new to Lodestone, start with the Overview &amp; Concepts page for whichever module you&#39;re working with. If you already know what you need to do, go straight to How-tos &amp; Workflows.</p><hr><p><em>This documentation covers the current Lodestone platform, updated to reflect all modules including Competitive Intelligence, Financial Forecast, Bento Grids, and the Lodestone API.</em></p>',62)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
